/**
 * The Website Shape Atlas as data, loaded and validated.
 *
 * `shape-atlas.json` (generated by `scripts/import-shape-atlas.ts` from the atlas HTML) carries
 * the atlas's own structure: 9 spines, 32 archetypes, a spine x spine compatibility matrix, one
 * transfer note per spine, 12 visual skins, 8 cross-cutting formats. `family-registry.json`
 * (hand-authored) maps each bundled Agency Site family package to the archetype and skin it was
 * built against. Both are loaded with `readFile` + `JSON.parse` (never import attributes) so tsc
 * and the test runner see the same code path.
 *
 * The validators here check structural integrity only (references resolve, the matrix is square,
 * symmetric, and diagonal 3) — invariants that must hold for any correctly-formed atlas, real or
 * a test fixture. The *specific* content of the checked-in real atlas (exactly 9 spines, 32
 * archetypes, 12 skins, 8 formats, 9 transfer notes) is asserted by `tests/atlas.test.ts`
 * directly against the loaded file, not enforced here.
 */

import { readFile } from 'node:fs/promises';
import path from 'node:path';

export type Spine = { code: string; kind: string; name: string; intent: string; steps: string[]; ctas: string[] };

export type Archetype = {
  id: string;
  spine: string;
  name: string;
  intent: string;
  steps: string[];
  sections: string[];
  primaryCta: string;
  closestTransfers: string[];
  keywords: string[];
};

export type TransferNote = { headline: string; transfer: string };
export type Format = { name: string; summary: string };

export type ShapeAtlas = {
  source: string;
  version: string;
  fetched: string;
  spines: Spine[];
  archetypes: Archetype[];
  /** `compatibility[sourceSpine][targetSpine]`: 0 (different spine) to 3 (close transfer). */
  compatibility: Record<string, Record<string, number>>;
  transferNotes: Record<string, TransferNote>;
  skins: string[];
  formats: Format[];
};

/** What kind of page a family builds — the route call's thirteenth question checks its answer
 * against the winning family's own `pageKind` (see `route.ts`'s `resolveRoute`); it is never a
 * routing signal on its own. */
export type PageKind = 'site' | 'app' | 'dashboard';

export type FamilyRegistryEntry = {
  family: string;
  archetype: string;
  /**
   * Further archetypes this family claims an EXACT match for, beyond its primary `archetype` —
   * for a family whose own brief spans more than one archetype of the same spine (`practice`
   * spans TL.01 and TL.02: a clinic can be the direct visit-and-book archetype or the specialist-
   * consult one, and it is the same family page either way). Every entry must share `spine` with
   * the primary `archetype` (`validateFamilyRegistry` checks this), and `route.ts`'s
   * `basisAgainstSpine`/`familyCriterion` both read it alongside the primary. Omitted for every
   * family with a single home archetype — the common case, and fully backward compatible.
   */
  archetypes?: readonly string[];
  spine: string;
  skin: string;
  skinInferred: boolean;
  summary: string;
  pageKind: PageKind;
  /**
   * True only for a family whose own fit REQUIRES an external buy step to link to (storefront):
   * this page links out to an existing shop, checkout or payment page/system, or a phone/email,
   * and never builds a cart, line items or a payment form itself. `resolveRoute`'s
   * `commerceOwnership` gate reads this: a confident `inline` answer (the brief asks THIS page to
   * build the cart/checkout/payment form itself, with no separate existing buy step) unroutes a
   * winning family that sets this flag, rather than publish a page that promises a buy step it
   * cannot build (route.ts, G7 task f8 root cause (a) — see eval-v7/G7-DIAGNOSIS.md). Omitted
   * (falsy) for every other family: the gate only ever fires for a family that actually claims
   * this requirement.
   */
  requiresExternalBuyStep?: boolean;
  /**
   * True only for a family that must win on an EXACT archetype match (`entry.archetype` or
   * `entry.archetypes`) and never merely on being in the same spine with no archetype confirmed
   * (`basisAgainstSpine`'s `same-spine` fallback, which fires even when `archetype_<CODE>`
   * answered `none`). Set on `fervor`: G7 task f8 root cause (c) — a catalog-fields-only stub
   * naming no agency/studio content at all (`Vertical: entertainment`, `Niche: sports`, `Use
   * case: marketing-site`, only motion/video-bg tags) got `archetype_TL: none` (Jev itself found
   * no TL archetype fit) yet still won the family vote at p=0.6-0.7 purely on fervor's own
   * tiebreaker prose matching its tag words, landing as a `same-spine` pick. Every reproduced
   * legitimate fervor case (agency/studio content in the brief) won on `exact` TL.05 already —
   * this flag only removes the `same-spine`/`compatible` fallback fervor never actually needed.
   * See eval-v7/G7-DIAGNOSIS.md. Omitted (falsy) for every other family, which keeps today's
   * same-spine fallback behavior unchanged for them.
   */
  requiresExactArchetype?: boolean;
  /**
   * True only for a family whose OWN archetype match never confers `exact` basis — it competes
   * on `same-spine` at most, exactly like every other same-spine family on that archetype. Set on
   * `maren` (routefix-r1 Grok audit, FIX finding, G7 task f8 root cause (b)/(d)): TL.06
   * ("Personal expert or portfolio") is the atlas's own general portfolio archetype — watson and
   * fervor (both TL.05) are legitimate same-spine competitors on a confident TL.06 answer too
   * (a photographer or freelancer brief can honestly read either way), and `exact` sole ownership
   * of TL.06 let maren's basis beat a HIGHER-probability watson/fervor pick inside the 0.02 tie
   * window purely on basis rank, not on what the family question itself favoured. Dropping
   * maren's exact claim (rather than inventing a narrower atlas archetype maren alone would own)
   * is the smaller fix: every reproduced DEV maren case wins on a clear, non-tied probability
   * margin (a comfortable lead over a trailing watson), so
   * losing the `exact` basis tier changes nothing for them. A genuine near-tie (within
   * TIE_EPSILON) against watson/fervor on the shared TL.06 answer is no longer won by maren on
   * basis; with equal `same-spine` bases it falls to skin match, then registry order. Outside
   * the tie window, probability decides. See eval-v7/G7-DIAGNOSIS.md.
   */
  sameSpineOnly?: boolean;
  /**
   * The family's own "not X" / "abstain" exclusion sentences, copied VERBATIM (byte-for-byte
   * substrings) from `summary` — never paraphrased, never a new sentence. `route.ts`'s general
   * exclusion gate (G7 task f8 run-3 re-plan) asks Jev, as one more choice question in the SAME
   * fan-out request, whether `brief` actually describes the case one of these clauses excludes,
   * even though the family otherwise won the `family` vote. A confident hit (>= `DEFAULT_THRESHOLD`)
   * unroutes the winner with reason `exclusion:<family>:<index>`, never retried
   * (`shouldRetryRoute`). This replaces having each exclusion sentence compete for attention
   * inside the family's own long, mostly-affirmative summary prose, where it reliably loses (see
   * eval-v7/G7-DIAGNOSIS.md section 7) — the summary text itself never changes; only this field
   * points at the sentences that were already there. `validateFamilyRegistry` enforces the
   * verbatim-substring invariant at load time so a hand-edit can never drift the two apart.
   * Omitted (or empty) for a family with no explicit self-exclusion sentence in its summary.
   */
  excludes?: readonly string[];
};

export type FamilyRegistry = { families: FamilyRegistryEntry[] };

/**
 * What a family's output is: a working `site`, or a `static-prototype` — the look of an app or
 * dashboard whose navigation, forms and controls are not wired (family pages ship
 * `script-src 'none'`). C16 of the GenUI production PRD: app and dashboard families are labelled
 * static prototypes in the UI and in the export.
 */
export type OutputScope = 'site' | 'static-prototype';

/** The one rule: a `site` page kind is a site, every other page kind is a static prototype. Every
 * product surface (daemon snapshot and AG-UI state, `od`, the web Build panel) derives the label
 * from here; the rendered page carries its own note and manifest field (the compiler's shared
 * `output-scope.ts`), and `tests/output-scope.test.ts` checks the two agree for every family. */
export function outputScopeOfPageKind(pageKind: PageKind): OutputScope {
  return pageKind === 'site' ? 'site' : 'static-prototype';
}

/** `family`'s output scope, from the registry's `pageKind`; `undefined` for a family the registry
 * does not list, or lists without a valid `pageKind` (never guessed). */
export function outputScopeOf(registry: FamilyRegistry, family: string): OutputScope | undefined {
  const entry = registry.families.find((candidate) => candidate.family === family);
  return entry && PAGE_KINDS.has(entry.pageKind) ? outputScopeOfPageKind(entry.pageKind) : undefined;
}

export const DEFAULT_ATLAS_PATH = path.join(import.meta.dirname, 'atlas/shape-atlas.json');
export const DEFAULT_REGISTRY_PATH = path.join(import.meta.dirname, 'atlas/family-registry.json');

/**
 * Structural integrity, independent of any particular atlas's content: every archetype's spine
 * exists, the compatibility matrix is square over exactly the spine codes, symmetric, and its
 * diagonal is always 3 (a spine transfers perfectly to itself).
 */
export function validateShapeAtlas(atlas: ShapeAtlas): void {
  if (atlas.spines.length === 0) throw new Error('shape atlas: at least one spine is required');
  const codes = atlas.spines.map((spine) => spine.code);
  const codeSet = new Set(codes);
  if (codeSet.size !== codes.length) throw new Error(`shape atlas: duplicate spine code among ${codes.join(', ')}`);

  for (const archetype of atlas.archetypes) {
    if (!codeSet.has(archetype.spine)) throw new Error(`shape atlas: archetype ${archetype.id} references unknown spine ${archetype.spine}`);
  }

  const matrixRows = Object.keys(atlas.compatibility);
  const rowSet = new Set(matrixRows);
  if (rowSet.size !== codeSet.size || ![...codeSet].every((code) => rowSet.has(code))) {
    throw new Error(`shape atlas: compatibility matrix rows (${matrixRows.join(', ')}) do not match spine codes (${codes.join(', ')})`);
  }
  for (const rowCode of codes) {
    const row = atlas.compatibility[rowCode]!;
    const columns = Object.keys(row);
    if (columns.length !== codes.length || !codes.every((code) => code in row)) {
      throw new Error(`shape atlas: compatibility row ${rowCode} is not square over the spine codes`);
    }
    if (row[rowCode] !== 3) throw new Error(`shape atlas: compatibility diagonal for ${rowCode} must be 3, got ${row[rowCode]}`);
    for (const columnCode of codes) {
      const forward = row[columnCode]!;
      const backward = atlas.compatibility[columnCode]![rowCode]!;
      if (forward !== backward) {
        throw new Error(`shape atlas: compatibility matrix is not symmetric between ${rowCode} and ${columnCode} (${forward} vs ${backward})`);
      }
    }
  }

  if (atlas.skins.length === 0) throw new Error('shape atlas: at least one skin is required');
  if (atlas.formats.length === 0) throw new Error('shape atlas: at least one format is required');
}

/** The only valid `FamilyRegistryEntry.pageKind` values — checked at load time because the
 * registry is hand-authored JSON, so nothing about `PageKind` being a closed TS union stops a
 * missing or misspelled value from reaching disk. */
const PAGE_KINDS = new Set<PageKind>(['site', 'app', 'dashboard']);

/** Whether `value` is one of the closed `PageKind` values. */
export function isPageKind(value: unknown): value is PageKind {
  return typeof value === 'string' && PAGE_KINDS.has(value as PageKind);
}

/** Every registry family must point at a real archetype (on the archetype's own spine), a real
 * skin, and a real pageKind. */
export function validateFamilyRegistry(registry: FamilyRegistry, atlas: ShapeAtlas): void {
  const archetypesById = new Map(atlas.archetypes.map((archetype) => [archetype.id, archetype]));
  const skinSet = new Set(atlas.skins);
  const seen = new Set<string>();
  for (const entry of registry.families) {
    if (seen.has(entry.family)) throw new Error(`family registry: duplicate family id ${entry.family}`);
    seen.add(entry.family);
    const archetype = archetypesById.get(entry.archetype);
    if (!archetype) throw new Error(`family registry: ${entry.family} references unknown archetype ${entry.archetype}`);
    if (archetype.spine !== entry.spine) {
      throw new Error(`family registry: ${entry.family} declares spine ${entry.spine} but archetype ${entry.archetype} is spine ${archetype.spine}`);
    }
    for (const extra of entry.archetypes ?? []) {
      const extraArchetype = archetypesById.get(extra);
      if (!extraArchetype) throw new Error(`family registry: ${entry.family} references unknown archetype ${extra} in archetypes`);
      if (extraArchetype.spine !== entry.spine) {
        throw new Error(`family registry: ${entry.family} declares spine ${entry.spine} but archetypes entry ${extra} is spine ${extraArchetype.spine}`);
      }
    }
    if (!skinSet.has(entry.skin)) throw new Error(`family registry: ${entry.family} references unknown skin ${entry.skin}`);
    if (!PAGE_KINDS.has(entry.pageKind)) throw new Error(`family registry: ${entry.family} references unknown pageKind ${entry.pageKind}`);
    for (const clause of entry.excludes ?? []) {
      if (clause.length === 0) throw new Error(`family registry: ${entry.family} has an empty excludes entry`);
      if (!entry.summary.includes(clause)) {
        throw new Error(`family registry: ${entry.family}'s excludes entry is not a verbatim substring of its own summary: ${JSON.stringify(clause)}`);
      }
    }
  }
}

async function readJsonFile(file: string): Promise<unknown> {
  return JSON.parse(await readFile(file, 'utf8')) as unknown;
}

export async function loadShapeAtlas(file: string = DEFAULT_ATLAS_PATH): Promise<ShapeAtlas> {
  const atlas = (await readJsonFile(file)) as ShapeAtlas;
  validateShapeAtlas(atlas);
  return atlas;
}

export async function loadFamilyRegistry(file: string = DEFAULT_REGISTRY_PATH): Promise<FamilyRegistry> {
  return (await readJsonFile(file)) as FamilyRegistry;
}

/** Loads and cross-validates both files together: what every caller (the router, the CLI) needs. */
export async function loadAtlasData(atlasFile?: string, registryFile?: string): Promise<{ atlas: ShapeAtlas; registry: FamilyRegistry }> {
  const [atlas, registry] = await Promise.all([loadShapeAtlas(atlasFile), loadFamilyRegistry(registryFile)]);
  validateFamilyRegistry(registry, atlas);
  return { atlas, registry };
}
